#include <Aevrynd/WorldOriginRuntime3D.h>
#include <iostream>
using namespace Aevrynd;
int main(){SceneECSRegistry3D scene;const auto entity=scene.Create();scene.SetTransform(entity,{{{100,2,-40}}});ChunkedVegetationWorld3D vegetation;VegetationAsset3D asset{{MeshHandle3D{1},MeshHandle3D{2},MeshHandle3D{3}}};Transform3D treeTransform{};treeTransform.position={104,0,-36};VegetationInstance3D tree{1,0,treeTransform.Matrix(),{{104,1,-36},2,{1,2,1}}};if(!vegetation.AttachChunkAtomic(1,std::span(&asset,1),std::span(&tree,1)))return 1;CollisionWorld3D collision;const auto collider=collision.CreateBox({{{108,1,-32},{1,1,1}},1,~0u,7,false});PhysicsWorld3D physics;RigidBodySettings3D bodySettings{};bodySettings.type=RigidBodyType3D::Dynamic;bodySettings.transform.position={110,3,-30};const auto body=physics.CreateBody(bodySettings);physics.Step(0);NavigationGrid3D navigation({{96,0,-48},8,8,1,64,true});CharacterController3D controller;controller.Reset({102,0,-38});Camera3D camera{{112,8,-52},{100,1,-40},{0,1,0},{}};DrawList draw;draw.SetOriginGeneration3D(1);WorldOriginRuntimeParticipant3D runtime({&scene,&vegetation,&collision,&physics,&navigation,&controller,&camera,&draw});WorldOriginCoordinator3D coordinator{};if(!coordinator.Register(runtime)||!coordinator.Request({{3,0,-1},{4,0,-8}})||!coordinator.ApplyFrameBoundary())return 2;const Vec3 delta{100,0,-40};if(scene.Transform(entity)->value.position.x!=0||scene.Transform(entity)->value.position.z!=0)return 3;const auto draws=vegetation.Query({camera,1,100,true,false});if(draws.empty()||draws[0].transform[0][3]!=4||draws[0].transform[2][3]!=4)return 4;const auto* box=collision.Get(collider);const auto* state=physics.GetBody(body);if(!box||box->bounds.center.x!=8||box->bounds.center.z!=8||!state||state->settings.transform.position.x!=10||state->previousPosition.x!=10)return 5;if(navigation.Settings().origin.x!=-4||controller.Position().x!=2||camera.position.x!=12||camera.target.x!=0||!draw.CameraCut3D()||draw.OriginGeneration3D()!=2)return 6;std::cout<<"world origin runtime smoke passed\n";}
